export const questions: Question[] = [
  {"id":"y2pe1-001","topicRef":"y2pe1","topicTitle":"Parametric Equations 30","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = t + 1, y = t^2\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Make the parameter the subject.","workingLatex":"x = t + 1 \\;\\Rightarrow\\; t = x - 1","explanation":"We want a relation between \\(x\\) and \\(y\\) alone, so first isolate \\(t\\) from the simpler equation. Here \\(x = t + 1\\) rearranges cleanly to \\(t = x - 1\\)."},{"stepNumber":2,"description":"Substitute into the other equation.","workingLatex":"y = t^2 = (x - 1)^2","explanation":"Replace every \\(t\\) in \\(y = t^2\\) by \\(x - 1\\). This eliminates the parameter and leaves a pure \\(x\\)–\\(y\\) relation."},{"stepNumber":3,"description":"State the Cartesian equation.","workingLatex":"y = (x - 1)^2","explanation":"This is a parabola, the curve \\(y = x^2\\) translated 1 unit to the right — a quick sanity check that the algebra is sensible."}],"finalAnswer":"\\(y = (x - 1)^2\\)."}},
  {"id":"y2pe1-002","topicRef":"y2pe1","topicTitle":"Parametric Equations 01","difficulty":"Foundation","questionText":"Find the Cartesian equation of \\(x = t, y = t^2\\).","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Read off the parameter.","workingLatex":"x = t \\;\\Rightarrow\\; t = x","explanation":"The first equation already gives \\(t\\) directly: the parameter equals \\(x\\). No rearranging is needed."},{"stepNumber":2,"description":"Substitute into \\(y = t^2\\).","workingLatex":"y = t^2 = x^2","explanation":"Replacing \\(t\\) by \\(x\\) in \\(y = t^2\\) eliminates the parameter immediately."}],"finalAnswer":"\\(y = x^2\\)."}},
  {"id":"y2pe1-003","topicRef":"y2pe1","topicTitle":"Parametric Equations 02","difficulty":"Foundation","questionText":"Find the Cartesian equation of the curve \\(x = 2t,\\ y = 3t\\).","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Isolate \\(t\\) from the \\(x\\)-equation.","workingLatex":"x = 2t \\;\\Rightarrow\\; t = \\tfrac{x}{2}","explanation":"Dividing \\(x = 2t\\) by 2 makes \\(t\\) the subject. Choosing the \\(x\\)-equation keeps the fractions simple."},{"stepNumber":2,"description":"Substitute into \\(y = 3t\\).","workingLatex":"y = 3t = 3 \\cdot \\tfrac{x}{2}","explanation":"Put \\(t = \\tfrac{x}{2}\\) into \\(y = 3t\\); the parameter is now gone."},{"stepNumber":3,"description":"Simplify.","workingLatex":"y = \\tfrac{3x}{2}","explanation":"This is a straight line through the origin with gradient \\(\\tfrac{3}{2}\\)."}],"finalAnswer":"\\(y = \\tfrac{3x}{2}\\)."}},
  {"id":"y2pe1-004","topicRef":"y2pe1","topicTitle":"Parametric Equations 03","difficulty":"Foundation","questionText":"Find the Cartesian equation of the curve \\(x = t - 2,\\ y = 3t + 1\\).","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Make \\(t\\) the subject of the \\(x\\)-equation.","workingLatex":"x = t - 2 \\;\\Rightarrow\\; t = x + 2","explanation":"Add 2 to both sides. The \\(x\\)-equation is linear in \\(t\\), so this is the easiest one to invert."},{"stepNumber":2,"description":"Substitute into \\(y = 3t + 1\\).","workingLatex":"y = 3(x + 2) + 1","explanation":"Replace \\(t\\) by \\(x + 2\\). Keep the bracket so the \\(\\times 3\\) is applied to the whole of \\(x + 2\\)."},{"stepNumber":3,"description":"Expand and simplify.","workingLatex":"y = 3x + 6 + 1 = 3x + 7","explanation":"Distribute the 3, then collect the constants. The result is a straight line of gradient 3."}],"finalAnswer":"\\(y = 3x + 7\\)."}},
  {"id":"y2pe1-005","topicRef":"y2pe1","topicTitle":"Parametric Equations 31","difficulty":"Standard","questionText":"Find the Cartesian equation of the curve \\(x = t^2,\\ y = t^3\\).","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Look for a relation avoiding square roots.","workingLatex":"x = t^2,\\quad y = t^3","explanation":"Solving \\(x = t^2\\) gives \\(t = \\pm\\sqrt{x}\\), which forces a \\(\\pm\\). It is cleaner to combine the equations so the \\(\\pm\\) disappears."},{"stepNumber":2,"description":"Square \\(y\\) to match powers of \\(t\\).","workingLatex":"y^2 = t^6 = (t^2)^3","explanation":"Both sides become even powers of \\(t\\). Writing \\(t^6 = (t^2)^3\\) prepares a direct substitution of \\(x\\)."},{"stepNumber":3,"description":"Substitute \\(x = t^2\\).","workingLatex":"y^2 = x^3","explanation":"This is the semicubical parabola. Squaring \\(y\\) was the key move: it removes the ambiguous square root entirely."}],"finalAnswer":"\\(y^2 = x^3\\) (semicubical parabola)."}},
  {"id":"y2pe1-006","topicRef":"y2pe1","topicTitle":"Parametric Equations 04","difficulty":"Foundation","questionText":"For \\(x = t + 1, y = t^2\\), find the point when \\(t = 2\\).","marks":1,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Substitute \\(t = 2\\) into \\(x\\).","workingLatex":"x = t + 1 = 2 + 1 = 3","explanation":"A point on a parametric curve is found by putting the given parameter value into both equations."},{"stepNumber":2,"description":"Substitute \\(t = 2\\) into \\(y\\).","workingLatex":"y = t^2 = 2^2 = 4","explanation":"Evaluate \\(y\\) at the same \\(t\\). Both coordinates must come from the one value \\(t = 2\\)."},{"stepNumber":3,"description":"State the point.","workingLatex":"(x, y) = (3, 4)","explanation":"The curve passes through \\((3, 4)\\) when \\(t = 2\\)."}],"finalAnswer":"\\((3, 4)\\)."}},
  {"id":"y2pe1-007","topicRef":"y2pe1","topicTitle":"Parametric Equations 05","difficulty":"Foundation","questionText":"A curve has parametric equations \\(x = t + 1,\\ y = t^2\\). Determine whether the point \\((5, 9)\\) lies on the curve.","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Find \\(t\\) from \\(x = 5\\).","workingLatex":"x = t + 1 = 5 \\;\\Rightarrow\\; t = 4","explanation":"Both coordinates must come from the same \\(t\\). The \\(x\\)-equation gives a single candidate, \\(t = 4\\)."},{"stepNumber":2,"description":"Test that \\(t\\) in the \\(y\\)-equation.","workingLatex":"y = t^2 = 4^2 = 16 \\ne 9","explanation":"At \\(t = 4\\) the curve gives \\(y = 16\\), not the required 9, so \\(t = 4\\) fails."},{"stepNumber":3,"description":"Check from the \\(y\\)-equation instead.","workingLatex":"y = t^2 = 9 \\;\\Rightarrow\\; t = \\pm 3","explanation":"Working the other way, \\(y = 9\\) needs \\(t = \\pm 3\\); these give \\(x = 4\\) or \\(x = -2\\), neither equal to 5."},{"stepNumber":4,"description":"Conclude.","workingLatex":"\\text{no common } t","explanation":"No single \\(t\\) satisfies both equations, so \\((5, 9)\\) is not on the curve."}],"finalAnswer":"No \\(t\\) satisfies both — \\((5, 9)\\) is not on the curve."}},
  {"id":"y2pe1-008","topicRef":"y2pe1","topicTitle":"Parametric Equations 32","difficulty":"Standard","questionText":"Find the Cartesian equation of the curve \\(x = 3t,\\ y = t^2 + 1\\).","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Isolate \\(t\\) from the linear equation.","workingLatex":"x = 3t \\;\\Rightarrow\\; t = \\tfrac{x}{3}","explanation":"Pick \\(x = 3t\\) because it is linear and inverts to a single value of \\(t\\)."},{"stepNumber":2,"description":"Substitute into \\(y = t^2 + 1\\).","workingLatex":"y = \\left(\\tfrac{x}{3}\\right)^2 + 1","explanation":"Replace \\(t\\) by \\(\\tfrac{x}{3}\\). Remember the whole of \\(\\tfrac{x}{3}\\) is squared."},{"stepNumber":3,"description":"Simplify.","workingLatex":"y = \\tfrac{x^2}{9} + 1","explanation":"Squaring the fraction gives \\(\\tfrac{x^2}{9}\\); a parabola shifted up by 1."}],"finalAnswer":"\\(y = \\tfrac{x^2}{9} + 1\\)."}},
  {"id":"y2pe1-009","topicRef":"y2pe1","topicTitle":"Parametric Equations 33","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = 2t + 1,\\ y = 4t^2\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Make \\(t\\) the subject of the \\(x\\)-equation.","workingLatex":"x = 2t + 1 \\;\\Rightarrow\\; t = \\tfrac{x - 1}{2}","explanation":"Subtract 1 and divide by 2 to invert the linear \\(x\\)-equation."},{"stepNumber":2,"description":"Substitute into \\(y = 4t^2\\).","workingLatex":"y = 4\\left(\\tfrac{x - 1}{2}\\right)^2 = 4 \\cdot \\tfrac{(x - 1)^2}{4}","explanation":"Square the bracket first, then multiply by 4; the 4 and the denominator 4 cancel."},{"stepNumber":3,"description":"Simplify.","workingLatex":"y = (x - 1)^2","explanation":"A parabola with vertex at \\((1, 0)\\)."}],"finalAnswer":"\\(y = (x - 1)^2\\)."}},
  {"id":"y2pe1-010","topicRef":"y2pe1","topicTitle":"Parametric Equations 34","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = t,\\ y = \\tfrac{1}{t}\\) (with \\(t \\ne 0\\)). Find its Cartesian form.","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric","reciprocal"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Multiply the two equations together.","workingLatex":"xy = t \\cdot \\tfrac{1}{t} = 1","explanation":"Multiplying eliminates \\(t\\) at once because \\(t \\cdot \\tfrac{1}{t} = 1\\); neater than substituting."},{"stepNumber":2,"description":"Rearrange to \\(y\\)-form.","workingLatex":"y = \\tfrac{1}{x}","explanation":"A rectangular hyperbola; \\(x \\ne 0\\) since \\(t \\ne 0\\)."}],"finalAnswer":"\\(y = \\tfrac{1}{x}\\)."}},
  {"id":"y2pe1-011","topicRef":"y2pe1","topicTitle":"Parametric Equations 06","difficulty":"Foundation","questionText":"A curve has parametric equations \\(x = 3t + 2,\\ y = 5 - t\\). Find its Cartesian equation.","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Make \\(t\\) the subject of \\(x\\).","workingLatex":"x = 3t + 2 \\;\\Rightarrow\\; t = \\tfrac{x - 2}{3}","explanation":"Subtract 2, divide by 3 to invert the \\(x\\)-equation."},{"stepNumber":2,"description":"Substitute into \\(y = 5 - t\\).","workingLatex":"y = 5 - \\tfrac{x - 2}{3} = \\tfrac{15 - (x - 2)}{3}","explanation":"Write 5 as \\(\\tfrac{15}{3}\\) over the common denominator before subtracting."},{"stepNumber":3,"description":"Simplify.","workingLatex":"y = \\tfrac{17 - x}{3}","explanation":"Combine the constants \\(15 + 2 = 17\\). A straight line of gradient \\(-\\tfrac{1}{3}\\)."}],"finalAnswer":"\\(y = \\tfrac{17 - x}{3}\\)."}},
  {"id":"y2pe1-012","topicRef":"y2pe1","topicTitle":"Parametric Equations 07","difficulty":"Foundation","questionText":"For \\(x = t^2 + 2, y = t - 1\\), find the point at \\(t = 0\\).","marks":1,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Substitute \\(t = 0\\) into \\(x\\).","workingLatex":"x = t^2 + 2 = 0 + 2 = 2","explanation":"Put the given \\(t = 0\\) into the \\(x\\)-equation; \\(0^2 = 0\\)."},{"stepNumber":2,"description":"Substitute \\(t = 0\\) into \\(y\\).","workingLatex":"y = t - 1 = 0 - 1 = -1","explanation":"Use the same \\(t\\) for \\(y\\)."},{"stepNumber":3,"description":"State the point.","workingLatex":"(2, -1)","explanation":"At \\(t = 0\\) the curve is at \\((2, -1)\\)."}],"finalAnswer":"\\((2, -1)\\)."}},
  {"id":"y2pe1-013","topicRef":"y2pe1","topicTitle":"Parametric Equations 08","difficulty":"Foundation","questionText":"A curve has parametric equations \\(x = t^2 + 2,\\ y = t - 1\\). Find the value of \\(t\\) for which \\(y = 0\\), and state the corresponding point.","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Set \\(y = 0\\) and solve for \\(t\\).","workingLatex":"y = t - 1 = 0 \\;\\Rightarrow\\; t = 1","explanation":"The condition is on \\(y\\), so use the \\(y\\)-equation to find the parameter."},{"stepNumber":2,"description":"Find \\(x\\) at that \\(t\\).","workingLatex":"x = t^2 + 2 = 1 + 2 = 3","explanation":"Substitute \\(t = 1\\) into the \\(x\\)-equation to locate the point."},{"stepNumber":3,"description":"State the result.","workingLatex":"t = 1,\\quad (3, 0)","explanation":"The curve meets \\(y = 0\\) at the point \\((3, 0)\\)."}],"finalAnswer":"\\(t = 1\\), point \\((3, 0)\\)."}},
  {"id":"y2pe1-014","topicRef":"y2pe1","topicTitle":"Parametric Equations 35","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = t^2 + 2,\\ y = t - 1\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Choose the easier equation to invert.","workingLatex":"y = t - 1 \\;\\Rightarrow\\; t = y + 1","explanation":"Here \\(y\\) is linear in \\(t\\) while \\(x\\) is quadratic, so isolate \\(t\\) from \\(y\\)."},{"stepNumber":2,"description":"Substitute into \\(x = t^2 + 2\\).","workingLatex":"x = (y + 1)^2 + 2","explanation":"Replace \\(t\\) by \\(y + 1\\); the result is naturally \\(x\\) in terms of \\(y\\)."},{"stepNumber":3,"description":"State the Cartesian equation.","workingLatex":"x = (y + 1)^2 + 2","explanation":"A sideways parabola opening in the \\(+x\\) direction with vertex \\((2, -1)\\)."}],"finalAnswer":"\\(x = (y + 1)^2 + 2\\)."}},
  {"id":"y2pe1-015","topicRef":"y2pe1","topicTitle":"Parametric Equations 36","difficulty":"Standard","questionText":"Find the Cartesian equation of the curve \\(x = e^t,\\ y = t\\).","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric","exp"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Invert the exponential.","workingLatex":"x = e^t \\;\\Rightarrow\\; t = \\ln x","explanation":"Take natural logs of \\(x = e^t\\); this is valid for \\(x > 0\\)."},{"stepNumber":2,"description":"Substitute into \\(y = t\\).","workingLatex":"y = \\ln x","explanation":"Since \\(y = t\\) and \\(t = \\ln x\\), the Cartesian equation is \\(y = \\ln x\\), defined for \\(x > 0\\)."}],"finalAnswer":"\\(y = \\ln x\\)."}},
  {"id":"y2pe1-016","topicRef":"y2pe1","topicTitle":"Parametric Equations 37","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = \\ln t,\\ y = t^2\\) (with \\(t > 0\\)). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric","log"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Invert the logarithm.","workingLatex":"x = \\ln t \\;\\Rightarrow\\; t = e^x","explanation":"Exponentiate both sides to free \\(t\\)."},{"stepNumber":2,"description":"Substitute into \\(y = t^2\\).","workingLatex":"y = (e^x)^2","explanation":"Replace \\(t\\) by \\(e^x\\); the whole exponential is squared."},{"stepNumber":3,"description":"Apply the power law.","workingLatex":"y = e^{2x}","explanation":"\\((e^x)^2 = e^{2x}\\): multiply the exponents."}],"finalAnswer":"\\(y = e^{2x}\\)."}},
  {"id":"y2pe1-017","topicRef":"y2pe1","topicTitle":"Parametric Equations 38","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = 2t^2,\\ y = 4t\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Make \\(t\\) the subject of the linear equation.","workingLatex":"y = 4t \\;\\Rightarrow\\; t = \\tfrac{y}{4}","explanation":"Use \\(y = 4t\\) because it is linear; this avoids a square root."},{"stepNumber":2,"description":"Substitute into \\(x = 2t^2\\).","workingLatex":"x = 2\\left(\\tfrac{y}{4}\\right)^2 = 2 \\cdot \\tfrac{y^2}{16} = \\tfrac{y^2}{8}","explanation":"Square the fraction, then multiply by 2 and simplify."},{"stepNumber":3,"description":"Rearrange to standard form.","workingLatex":"y^2 = 8x","explanation":"Multiply through by 8. A parabola opening along the \\(x\\)-axis."}],"finalAnswer":"\\(y^2 = 8x\\)."}},
  {"id":"y2pe1-018","topicRef":"y2pe1","topicTitle":"Parametric Equations 63","difficulty":"Challenge","questionText":"Eliminate \\(t\\) from \\(x = t + \\tfrac{1}{t}, y = t - \\tfrac{1}{t}\\).","marks":4,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Square both parametric equations.","workingLatex":"x^2 = t^2 + 2 + \\tfrac{1}{t^2},\\quad y^2 = t^2 - 2 + \\tfrac{1}{t^2}","explanation":"Squaring \\(t \\pm \\tfrac{1}{t}\\) gives \\(t^2 \\pm 2 + \\tfrac{1}{t^2}\\); the cross term \\(2 \\cdot t \\cdot \\tfrac{1}{t} = 2\\) is the key piece."},{"stepNumber":2,"description":"Subtract to cancel \\(t^2 + \\tfrac{1}{t^2}\\).","workingLatex":"x^2 - y^2 = (t^2 + 2 + \\tfrac{1}{t^2}) - (t^2 - 2 + \\tfrac{1}{t^2})","explanation":"Subtracting removes the awkward \\(t^2\\) and \\(\\tfrac{1}{t^2}\\) terms, leaving only the constants."},{"stepNumber":3,"description":"Simplify.","workingLatex":"x^2 - y^2 = 4","explanation":"The \\(+2\\) and \\(-(-2)\\) combine to \\(4\\). This is a hyperbola."}],"finalAnswer":"\\(x^2 - y^2 = 4\\) (hyperbola)."}},
  {"id":"y2pe1-019","topicRef":"y2pe1","topicTitle":"Parametric Equations 39","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = t^2 - 1,\\ y = 2t\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Invert the linear equation.","workingLatex":"y = 2t \\;\\Rightarrow\\; t = \\tfrac{y}{2}","explanation":"Use \\(y = 2t\\) to get \\(t\\) without introducing a square root."},{"stepNumber":2,"description":"Substitute into \\(x = t^2 - 1\\).","workingLatex":"x = \\left(\\tfrac{y}{2}\\right)^2 - 1 = \\tfrac{y^2}{4} - 1","explanation":"Square the fraction, then keep the \\(-1\\)."},{"stepNumber":3,"description":"Rearrange.","workingLatex":"y^2 = 4(x + 1)","explanation":"Add 1 and multiply by 4. A parabola with vertex \\((-1, 0)\\)."}],"finalAnswer":"\\(x = \\tfrac{y^2}{4} - 1\\), i.e. \\(y^2 = 4(x + 1)\\)."}},
  {"id":"y2pe1-020","topicRef":"y2pe1","topicTitle":"Parametric Equations 40","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = 2t + 3,\\ y = 1 - t\\) for \\(0 \\le t \\le 2\\). Find the endpoints of the curve and state its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Find the endpoints from the parameter range.","workingLatex":"t = 0:(3, 1);\\quad t = 2:(7, -1)","explanation":"Evaluate both equations at the ends \\(t = 0\\) and \\(t = 2\\) of the allowed range."},{"stepNumber":2,"description":"Make \\(t\\) the subject of \\(x\\).","workingLatex":"x = 2t + 3 \\;\\Rightarrow\\; t = \\tfrac{x - 3}{2}","explanation":"Subtract 3 and divide by 2."},{"stepNumber":3,"description":"Substitute into \\(y = 1 - t\\).","workingLatex":"y = 1 - \\tfrac{x - 3}{2} = \\tfrac{5 - x}{2}","explanation":"Over a common denominator: \\(1 - \\tfrac{x-3}{2} = \\tfrac{2-(x-3)}{2} = \\tfrac{5-x}{2}\\)."},{"stepNumber":4,"description":"State the line segment.","workingLatex":"y = -\\tfrac{x}{2} + \\tfrac{5}{2}","explanation":"The curve is the segment of this line between \\((3, 1)\\) and \\((7, -1)\\)."}],"finalAnswer":"Line segment from \\((3, 1)\\) to \\((7, -1)\\); equation \\(y = -\\tfrac{x}{2} + \\tfrac{5}{2}\\)."}},
  {"id":"y2pe1-021","topicRef":"y2pe1","topicTitle":"Parametric Equations 09","difficulty":"Foundation","questionText":"Show that \\(x = r\\cos\\theta, y = r\\sin\\theta\\) is a circle of radius \\(r\\).","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric","trig"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Square each equation.","workingLatex":"x^2 = r^2\\cos^2\\theta,\\quad y^2 = r^2\\sin^2\\theta","explanation":"We aim to use \\(\\cos^2\\theta + \\sin^2\\theta = 1\\), so square both so the trig functions appear squared."},{"stepNumber":2,"description":"Add the two results.","workingLatex":"x^2 + y^2 = r^2(\\cos^2\\theta + \\sin^2\\theta)","explanation":"Adding factors out the common \\(r^2\\) and groups the squared trig terms."},{"stepNumber":3,"description":"Apply the Pythagorean identity.","workingLatex":"x^2 + y^2 = r^2","explanation":"Since \\(\\cos^2\\theta + \\sin^2\\theta = 1\\), this is a circle of radius \\(r\\) centred at the origin, as required."}],"finalAnswer":"\\(x^2 + y^2 = r^2\\)."}},
  {"id":"y2pe1-022","topicRef":"y2pe1","topicTitle":"Parametric Equations 41","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = 3\\cos t,\\ y = 2\\sin t\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric","ellipse"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Isolate the trig functions.","workingLatex":"\\cos t = \\tfrac{x}{3},\\quad \\sin t = \\tfrac{y}{2}","explanation":"Divide each equation by its amplitude to prepare for the Pythagorean identity."},{"stepNumber":2,"description":"Apply \\(\\cos^2 t + \\sin^2 t = 1\\).","workingLatex":"\\left(\\tfrac{x}{3}\\right)^2 + \\left(\\tfrac{y}{2}\\right)^2 = 1","explanation":"Square each and add; the identity eliminates \\(t\\)."},{"stepNumber":3,"description":"Write in standard form.","workingLatex":"\\tfrac{x^2}{9} + \\tfrac{y^2}{4} = 1","explanation":"An ellipse with semi-axes 3 and 2."}],"finalAnswer":"\\(\\tfrac{x^2}{9} + \\tfrac{y^2}{4} = 1\\)."}},
  {"id":"y2pe1-023","topicRef":"y2pe1","topicTitle":"Parametric Equations 10","difficulty":"Foundation","questionText":"A curve has parametric equations \\(x = \\cos t,\\ y = \\sin t\\). Find its Cartesian equation.","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric","trig"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Square and add the equations.","workingLatex":"x^2 + y^2 = \\cos^2 t + \\sin^2 t","explanation":"Squaring each and adding sets up the Pythagorean identity."},{"stepNumber":2,"description":"Apply the identity.","workingLatex":"x^2 + y^2 = 1","explanation":"\\(\\cos^2 t + \\sin^2 t = 1\\): the unit circle."}],"finalAnswer":"\\(x^2 + y^2 = 1\\)."}},
  {"id":"y2pe1-024","topicRef":"y2pe1","topicTitle":"Parametric Equations 42","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = 2 + \\cos t,\\ y = 1 + \\sin t\\). Find its Cartesian equation and describe the curve.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric","circle"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Isolate the trig terms.","workingLatex":"\\cos t = x - 2,\\quad \\sin t = y - 1","explanation":"Subtract the constants so each side is a single trig function."},{"stepNumber":2,"description":"Apply the Pythagorean identity.","workingLatex":"(x - 2)^2 + (y - 1)^2 = \\cos^2 t + \\sin^2 t = 1","explanation":"Square and add; the identity removes \\(t\\)."},{"stepNumber":3,"description":"Describe the curve.","workingLatex":"(x - 2)^2 + (y - 1)^2 = 1","explanation":"A circle of radius 1 centred at \\((2, 1)\\)."}],"finalAnswer":"Circle centre \\((2, 1)\\), radius 1."}},
  {"id":"y2pe1-025","topicRef":"y2pe1","topicTitle":"Parametric Equations 43","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = 1 + 2\\cos t,\\ y = 3 + 2\\sin t\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric","circle"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Isolate the trig functions.","workingLatex":"\\cos t = \\tfrac{x - 1}{2},\\quad \\sin t = \\tfrac{y - 3}{2}","explanation":"Subtract the centre coordinates and divide by the radius 2."},{"stepNumber":2,"description":"Apply \\(\\cos^2 t + \\sin^2 t = 1\\).","workingLatex":"\\left(\\tfrac{x - 1}{2}\\right)^2 + \\left(\\tfrac{y - 3}{2}\\right)^2 = 1","explanation":"Square each and add."},{"stepNumber":3,"description":"Clear the denominators.","workingLatex":"(x - 1)^2 + (y - 3)^2 = 4","explanation":"Multiply through by \\(2^2 = 4\\). A circle of radius 2 centred at \\((1, 3)\\)."}],"finalAnswer":"\\((x - 1)^2 + (y - 3)^2 = 4\\)."}},
  {"id":"y2pe1-026","topicRef":"y2pe1","topicTitle":"Parametric Equations 11","difficulty":"Foundation","questionText":"Find the point on the unit circle at \\(\\theta = \\tfrac{\\pi}{4}\\).","marks":1,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Use the unit-circle parametrisation.","workingLatex":"x = \\cos\\theta,\\quad y = \\sin\\theta","explanation":"On the unit circle the point at angle \\(\\theta\\) is \\((\\cos\\theta, \\sin\\theta)\\)."},{"stepNumber":2,"description":"Evaluate the trig at \\(\\theta = \\tfrac{\\pi}{4}\\).","workingLatex":"\\cos\\tfrac{\\pi}{4} = \\sin\\tfrac{\\pi}{4} = \\tfrac{\\sqrt 2}{2}","explanation":"Both equal \\(\\tfrac{\\sqrt 2}{2}\\) since \\(\\tfrac{\\pi}{4}\\) is the 45° angle."},{"stepNumber":3,"description":"State the point.","workingLatex":"\\left(\\tfrac{\\sqrt 2}{2},\\ \\tfrac{\\sqrt 2}{2}\\right)","explanation":"This sits on the line \\(y = x\\), as expected for 45°."}],"finalAnswer":"\\((\\tfrac{\\sqrt 2}{2}, \\tfrac{\\sqrt 2}{2})\\)."}},
  {"id":"y2pe1-027","topicRef":"y2pe1","topicTitle":"Parametric Equations 44","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = e^t,\\ y = e^{2t}\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Spot that \\(y\\) is a power of \\(x\\).","workingLatex":"y = e^{2t} = (e^t)^2","explanation":"Use the power law \\(e^{2t} = (e^t)^2\\); note that \\(e^t\\) is exactly \\(x\\)."},{"stepNumber":2,"description":"Substitute \\(x = e^t\\).","workingLatex":"y = x^2","explanation":"Replace \\(e^t\\) by \\(x\\). Since \\(x = e^t > 0\\), the curve is the part of \\(y = x^2\\) with \\(x > 0\\)."}],"finalAnswer":"\\(y = x^2\\)."}},
  {"id":"y2pe1-028","topicRef":"y2pe1","topicTitle":"Parametric Equations 45","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = t + 2,\\ y = t^2 + 4t\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Invert the \\(x\\)-equation.","workingLatex":"x = t + 2 \\;\\Rightarrow\\; t = x - 2","explanation":"Subtract 2 from both sides."},{"stepNumber":2,"description":"Substitute into \\(y = t^2 + 4t\\).","workingLatex":"y = (x - 2)^2 + 4(x - 2)","explanation":"Replace each \\(t\\) by \\(x - 2\\); keep both brackets."},{"stepNumber":3,"description":"Expand and simplify.","workingLatex":"y = (x^2 - 4x + 4) + (4x - 8) = x^2 - 4","explanation":"Expand each bracket then collect: \\(-4x + 4x = 0\\) and \\(4 - 8 = -4\\)."}],"finalAnswer":"\\(y = (x - 2)^2 + 4(x - 2) = x^2 - 4\\)."}},
  {"id":"y2pe1-029","topicRef":"y2pe1","topicTitle":"Parametric Equations 12","difficulty":"Foundation","questionText":"A curve has parametric equations \\(x = t^2,\\ y = 3t\\). Find the point on the curve at \\(t = -1\\).","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Substitute \\(t = -1\\) into \\(x\\).","workingLatex":"x = t^2 = (-1)^2 = 1","explanation":"Squaring \\(-1\\) gives \\(+1\\); a common slip is to leave it negative."},{"stepNumber":2,"description":"Substitute \\(t = -1\\) into \\(y\\).","workingLatex":"y = 3t = 3(-1) = -3","explanation":"Evaluate \\(y\\) at the same \\(t\\)."},{"stepNumber":3,"description":"State the point.","workingLatex":"(1, -3)","explanation":"The curve passes through \\((1, -3)\\) at \\(t = -1\\)."}],"finalAnswer":"\\((1, -3)\\)."}},
  {"id":"y2pe1-030","topicRef":"y2pe1","topicTitle":"Parametric Equations 46","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = t^3,\\ y = 3t\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Invert the linear equation.","workingLatex":"y = 3t \\;\\Rightarrow\\; t = \\tfrac{y}{3}","explanation":"Use \\(y = 3t\\); it is linear and inverts to a single value."},{"stepNumber":2,"description":"Substitute into \\(x = t^3\\).","workingLatex":"x = \\left(\\tfrac{y}{3}\\right)^3 = \\tfrac{y^3}{27}","explanation":"Cube the fraction: numerator \\(y^3\\), denominator \\(3^3 = 27\\)."},{"stepNumber":3,"description":"State the Cartesian equation.","workingLatex":"x = \\tfrac{y^3}{27}","explanation":"A cubic curve given as \\(x\\) in terms of \\(y\\)."}],"finalAnswer":"\\(x = (\\tfrac{y}{3})^3 = \\tfrac{y^3}{27}\\)."}},
  {"id":"y2pe1-031","topicRef":"y2pe1","topicTitle":"Parametric Equations 64","difficulty":"Challenge","questionText":"Is the cycloid \\(x = t - \\sin t, y = 1 - \\cos t\\) easily expressible in Cartesian form?","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Try to isolate \\(t\\) from one equation.","workingLatex":"y = 1 - \\cos t \\;\\Rightarrow\\; t = \\arccos(1 - y)","explanation":"From \\(y\\) we can get \\(t\\), but it is multivalued and only valid on a limited range."},{"stepNumber":2,"description":"Substitute into \\(x = t - \\sin t\\).","workingLatex":"x = \\arccos(1 - y) - \\sin\\big(\\arccos(1 - y)\\big)","explanation":"The \\(t\\) and \\(\\sin t\\) appear *separately*, so eliminating \\(t\\) leaves an inverse-trig expression that cannot be tidied into a simple relation."},{"stepNumber":3,"description":"Conclude.","workingLatex":"\\text{keep parametric form}","explanation":"The cycloid has no neat closed-form Cartesian equation, so it is best left in parametric form."}],"finalAnswer":"No simple closed form; keep parametric."}},
  {"id":"y2pe1-032","topicRef":"y2pe1","topicTitle":"Parametric Equations 47","difficulty":"Standard","questionText":"Find values of \\(t\\) for which \\(y = 1 - \\cos t = 0\\).","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Set \\(y = 0\\).","workingLatex":"1 - \\cos t = 0","explanation":"We want the parameter values that make the height \\(y\\) zero."},{"stepNumber":2,"description":"Solve for \\(\\cos t\\).","workingLatex":"\\cos t = 1","explanation":"Rearrange: the cosine must equal 1."},{"stepNumber":3,"description":"Solve over all \\(t\\).","workingLatex":"t = 2k\\pi,\\quad k \\in \\mathbb{Z}","explanation":"\\(\\cos t = 1\\) only at multiples of \\(2\\pi\\). These are the points where the cycloid touches the \\(x\\)-axis."}],"finalAnswer":"\\(t = 2k\\pi\\) for integer \\(k\\)."}},
  {"id":"y2pe1-033","topicRef":"y2pe1","topicTitle":"Parametric Equations 13","difficulty":"Foundation","questionText":"For \\(x = t, y = t^2\\), list points for \\(t = -2, -1, 0, 1, 2\\).","marks":3,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Substitute each \\(t\\) into \\(x = t\\) and \\(y = t^2\\).","workingLatex":"x = t,\\quad y = t^2","explanation":"For a table of points, evaluate both coordinates at each parameter value in turn."},{"stepNumber":2,"description":"Evaluate at \\(t = -2, -1, 0, 1, 2\\).","workingLatex":"(-2,4),\\ (-1,1),\\ (0,0),\\ (1,1),\\ (2,4)","explanation":"Square each \\(t\\) for \\(y\\); note \\(t = \\pm 2\\) give the same \\(y = 4\\), so the curve is symmetric about the \\(y\\)-axis."}],"finalAnswer":"\\((-2, 4), (-1, 1), (0, 0), (1, 1), (2, 4)\\)."}},
  {"id":"y2pe1-034","topicRef":"y2pe1","topicTitle":"Parametric Equations 48","difficulty":"Standard","questionText":"An ellipse has parametric equations \\(x = 2\\cos\\theta,\\ y = 3\\sin\\theta\\). Find the point on it at \\(\\theta = \\tfrac{\\pi}{3}\\).","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Evaluate \\(x\\) at \\(\\theta = \\tfrac{\\pi}{3}\\).","workingLatex":"x = 2\\cos\\tfrac{\\pi}{3} = 2 \\cdot \\tfrac{1}{2} = 1","explanation":"Use \\(\\cos\\tfrac{\\pi}{3} = \\tfrac12\\)."},{"stepNumber":2,"description":"Evaluate \\(y\\) at \\(\\theta = \\tfrac{\\pi}{3}\\).","workingLatex":"y = 3\\sin\\tfrac{\\pi}{3} = 3 \\cdot \\tfrac{\\sqrt 3}{2} = \\tfrac{3\\sqrt 3}{2}","explanation":"Use \\(\\sin\\tfrac{\\pi}{3} = \\tfrac{\\sqrt3}{2}\\)."},{"stepNumber":3,"description":"State the point.","workingLatex":"\\left(1,\\ \\tfrac{3\\sqrt 3}{2}\\right)","explanation":"Both coordinates come from the one angle \\(\\theta = \\tfrac{\\pi}{3}\\)."}],"finalAnswer":"\\((1, \\tfrac{3\\sqrt 3}{2})\\)."}},
  {"id":"y2pe1-035","topicRef":"y2pe1","topicTitle":"Parametric Equations 14","difficulty":"Foundation","questionText":"Is the point \\((2, 3)\\) on the curve \\(x = 2t, y = 3t\\)?","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Find \\(t\\) from \\(x = 2\\).","workingLatex":"x = 2t = 2 \\;\\Rightarrow\\; t = 1","explanation":"Test whether one \\(t\\) reproduces both coordinates. Start with \\(x\\)."},{"stepNumber":2,"description":"Check \\(y\\) at that \\(t\\).","workingLatex":"y = 3t = 3(1) = 3","explanation":"At \\(t = 1\\) we get \\(y = 3\\), which matches the required \\(y\\)-coordinate."},{"stepNumber":3,"description":"Conclude.","workingLatex":"(2, 3)\\ \\text{lies on the curve at } t = 1","explanation":"Since the single value \\(t = 1\\) gives both \\(x = 2\\) and \\(y = 3\\), the point is on the curve."}],"finalAnswer":"Yes, at \\(t = 1\\)."}},
  {"id":"y2pe1-036","topicRef":"y2pe1","topicTitle":"Parametric Equations 49","difficulty":"Standard","questionText":"Is \\((4, 9)\\) on \\(x = t^2, y = t^3\\)?","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Find \\(t\\) from \\(x = 4\\).","workingLatex":"x = t^2 = 4 \\;\\Rightarrow\\; t = \\pm 2","explanation":"Because \\(x = t^2\\), there are two candidate parameter values."},{"stepNumber":2,"description":"Test each in \\(y = t^3\\).","workingLatex":"y = (\\pm 2)^3 = \\pm 8","explanation":"Cubing keeps the sign, giving \\(y = 8\\) or \\(y = -8\\); neither is 9."},{"stepNumber":3,"description":"Conclude.","workingLatex":"y \\ne 9 \\text{ for either } t","explanation":"No parameter value gives both \\(x = 4\\) and \\(y = 9\\), so \\((4, 9)\\) is not on the curve."}],"finalAnswer":"No."}},
  {"id":"y2pe1-037","topicRef":"y2pe1","topicTitle":"Parametric Equations 15","difficulty":"Foundation","questionText":"Write \\(y = 2x + 3\\) in parametric form.","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Let \\(x\\) be the parameter.","workingLatex":"x = t","explanation":"A Cartesian curve \\(y = f(x)\\) is parametrised most simply by setting \\(x = t\\)."},{"stepNumber":2,"description":"Write \\(y\\) in terms of \\(t\\).","workingLatex":"y = 2t + 3","explanation":"Substitute \\(x = t\\) into \\(y = 2x + 3\\). This reproduces the same line."}],"finalAnswer":"\\(x = t, y = 2t + 3\\)."}},
  {"id":"y2pe1-038","topicRef":"y2pe1","topicTitle":"Parametric Equations 16","difficulty":"Foundation","questionText":"Write \\(y = x^2 - 4\\) in parametric form.","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Set \\(x = t\\).","workingLatex":"x = t","explanation":"Take the parameter to be \\(x\\) itself — the standard trick for turning \\(y = f(x)\\) into parametric form."},{"stepNumber":2,"description":"Express \\(y\\) in \\(t\\).","workingLatex":"y = t^2 - 4","explanation":"Replace \\(x\\) by \\(t\\) in \\(y = x^2 - 4\\)."}],"finalAnswer":"\\(x = t, y = t^2 - 4\\)."}},
  {"id":"y2pe1-039","topicRef":"y2pe1","topicTitle":"Parametric Equations 50","difficulty":"Standard","questionText":"Write \\(x^2 + y^2 = 25\\) in parametric form.","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric","circle"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Recognise a circle of radius 5.","workingLatex":"x^2 + y^2 = 25 = 5^2","explanation":"A circle centred at the origin parametrises with cosine and sine scaled by the radius."},{"stepNumber":2,"description":"Write the parametrisation.","workingLatex":"x = 5\\cos\\theta,\\quad y = 5\\sin\\theta","explanation":"Then \\(x^2 + y^2 = 25(\\cos^2\\theta + \\sin^2\\theta) = 25\\), recovering the circle."}],"finalAnswer":"\\(x = 5\\cos\\theta, y = 5\\sin\\theta\\)."}},
  {"id":"y2pe1-040","topicRef":"y2pe1","topicTitle":"Parametric Equations 51","difficulty":"Standard","questionText":"Write \\((x - 3)^2 + (y + 1)^2 = 9\\) in parametric form.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric","circle"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Read off the centre and radius.","workingLatex":"\\text{centre } (3, -1),\\ r = 3","explanation":"Compare with \\((x - a)^2 + (y - b)^2 = r^2\\): here \\(a = 3\\), \\(b = -1\\), \\(r^2 = 9\\)."},{"stepNumber":2,"description":"Shift the standard circle parametrisation.","workingLatex":"x = 3 + 3\\cos\\theta,\\quad y = -1 + 3\\sin\\theta","explanation":"Add the centre coordinates to \\(r\\cos\\theta\\) and \\(r\\sin\\theta\\)."},{"stepNumber":3,"description":"Check.","workingLatex":"(x - 3)^2 + (y + 1)^2 = 9\\cos^2\\theta + 9\\sin^2\\theta = 9","explanation":"The identity confirms the parametrisation traces the given circle."}],"finalAnswer":"\\(x = 3 + 3\\cos\\theta, y = -1 + 3\\sin\\theta\\)."}},
  {"id":"y2pe1-041","topicRef":"y2pe1","topicTitle":"Parametric Equations 17","difficulty":"Foundation","questionText":"State the range of \\(x\\) values for \\(x = t^2\\) with \\(t \\ge 0\\).","marks":1,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Consider the squared parameter.","workingLatex":"x = t^2","explanation":"We need the set of possible \\(x\\)-values as \\(t\\) ranges over \\(t \\ge 0\\)."},{"stepNumber":2,"description":"Use that a square is non-negative.","workingLatex":"t^2 \\ge 0 \\;\\Rightarrow\\; x \\ge 0","explanation":"Any real square is \\(\\ge 0\\); with \\(t \\ge 0\\), \\(x = t^2\\) still covers all of \\([0, \\infty)\\)."}],"finalAnswer":"\\(x \\ge 0\\)."}},
  {"id":"y2pe1-042","topicRef":"y2pe1","topicTitle":"Parametric Equations 18","difficulty":"Foundation","questionText":"State the range of \\(y\\) for \\(y = \\sin t\\).","marks":1,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Recall the range of sine.","workingLatex":"-1 \\le \\sin t \\le 1","explanation":"The sine function oscillates between \\(-1\\) and \\(1\\) for all real \\(t\\)."},{"stepNumber":2,"description":"Translate to \\(y\\).","workingLatex":"-1 \\le y \\le 1","explanation":"Since \\(y = \\sin t\\), \\(y\\) takes exactly these values."}],"finalAnswer":"\\(-1 \\le y \\le 1\\)."}},
  {"id":"y2pe1-043","topicRef":"y2pe1","topicTitle":"Parametric Equations 19","difficulty":"Foundation","questionText":"State the range of \\(y\\) for \\(y = t^2 + 1\\).","marks":1,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Bound the squared term.","workingLatex":"t^2 \\ge 0","explanation":"The square \\(t^2\\) is never negative, with minimum 0 at \\(t = 0\\)."},{"stepNumber":2,"description":"Add 1.","workingLatex":"y = t^2 + 1 \\ge 1","explanation":"Adding 1 shifts the minimum up to 1, so \\(y \\ge 1\\)."}],"finalAnswer":"\\(y \\ge 1\\)."}},
  {"id":"y2pe1-044","topicRef":"y2pe1","topicTitle":"Parametric Equations 52","difficulty":"Standard","questionText":"Write parametric equations for the upper semicircle of radius 3 centred at origin.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Parametrise a radius-3 circle.","workingLatex":"x = 3\\cos t,\\quad y = 3\\sin t","explanation":"Start from the full circle of radius 3 centred at the origin."},{"stepNumber":2,"description":"Restrict to the upper half.","workingLatex":"0 \\le t \\le \\pi","explanation":"On \\([0, \\pi]\\) the sine is \\(\\ge 0\\), so \\(y \\ge 0\\): this traces only the upper semicircle, from \\((3,0)\\) to \\((-3,0)\\)."}],"finalAnswer":"\\(x = 3\\cos t, y = 3\\sin t\\) for \\(0 \\le t \\le \\pi\\)."}},
  {"id":"y2pe1-045","topicRef":"y2pe1","topicTitle":"Parametric Equations 53","difficulty":"Standard","questionText":"Write parametric equations for the line segment from \\((1, 2)\\) to \\((4, 8)\\).","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Use the start point and direction vector.","workingLatex":"\\Delta = (4 - 1,\\ 8 - 2) = (3, 6)","explanation":"A segment from \\(A\\) to \\(B\\) is \\(A + t(B - A)\\); compute the displacement \\(B - A\\)."},{"stepNumber":2,"description":"Write the parametrisation.","workingLatex":"x = 1 + 3t,\\quad y = 2 + 6t","explanation":"Add \\(t\\) times the direction to the start point \\((1, 2)\\)."},{"stepNumber":3,"description":"State the parameter range.","workingLatex":"0 \\le t \\le 1","explanation":"\\(t = 0\\) gives \\(A = (1, 2)\\) and \\(t = 1\\) gives \\(B = (4, 8)\\), so \\([0,1]\\) traces exactly the segment."}],"finalAnswer":"\\(x = 1 + 3t, y = 2 + 6t\\) for \\(0 \\le t \\le 1\\)."}},
  {"id":"y2pe1-046","topicRef":"y2pe1","topicTitle":"Parametric Equations 54","difficulty":"Standard","questionText":"Write \\(y^2 = 4x\\) parametrically.","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Choose \\(y = 2t\\) to clear the constant.","workingLatex":"y = 2t \\;\\Rightarrow\\; y^2 = 4t^2","explanation":"Picking \\(y = 2t\\) makes \\(y^2 = 4t^2\\) match the right-hand side \\(4x\\) neatly."},{"stepNumber":2,"description":"Match with \\(y^2 = 4x\\).","workingLatex":"4t^2 = 4x \\;\\Rightarrow\\; x = t^2","explanation":"Comparing \\(y^2 = 4x\\) with \\(y^2 = 4t^2\\) forces \\(x = t^2\\)."}],"finalAnswer":"\\(x = t^2, y = 2t\\)."}},
  {"id":"y2pe1-047","topicRef":"y2pe1","topicTitle":"Parametric Equations 65","difficulty":"Challenge","questionText":"Write \\(x^2 - y^2 = 1\\) parametrically.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric","hyperbola"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Match the form \\(x^2 - y^2 = 1\\) to an identity.","workingLatex":"\\sec^2 t - \\tan^2 t = 1","explanation":"The identity \\(\\sec^2 t - \\tan^2 t = 1\\) has exactly the same shape as the equation."},{"stepNumber":2,"description":"Read off a parametrisation.","workingLatex":"x = \\sec t,\\quad y = \\tan t","explanation":"Then \\(x^2 - y^2 = \\sec^2 t - \\tan^2 t = 1\\)."},{"stepNumber":3,"description":"Note an alternative.","workingLatex":"x = \\cosh t,\\quad y = \\sinh t","explanation":"Since \\(\\cosh^2 t - \\sinh^2 t = 1\\), the hyperbolic functions give another valid parametrisation."}],"finalAnswer":"\\(x = \\sec t, y = \\tan t\\) (or \\(x = \\cosh t, y = \\sinh t\\))."}},
  {"id":"y2pe1-048","topicRef":"y2pe1","topicTitle":"Parametric Equations 55","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = t + 3,\\ y = t^2 - 4\\). Find the coordinates of the points where it crosses the \\(x\\)-axis.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Set \\(y = 0\\) for the \\(x\\)-axis.","workingLatex":"t^2 - 4 = 0 \\;\\Rightarrow\\; t = \\pm 2","explanation":"The curve crosses the \\(x\\)-axis where \\(y = 0\\); solve the quadratic in \\(t\\)."},{"stepNumber":2,"description":"Find \\(x\\) at each \\(t\\).","workingLatex":"t = 2: x = 5;\\quad t = -2: x = 1","explanation":"Substitute each parameter value into \\(x = t + 3\\)."},{"stepNumber":3,"description":"State the crossing points.","workingLatex":"(5, 0)\\ \\text{and}\\ (1, 0)","explanation":"Two distinct crossings, at \\(t = 2\\) and \\(t = -2\\)."}],"finalAnswer":"\\((5, 0)\\) and \\((1, 0)\\)."}},
  {"id":"y2pe1-049","topicRef":"y2pe1","topicTitle":"Parametric Equations 56","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = 3t,\\ y = t^2 + 1\\). Find its \\(y\\)-intercept.","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Set \\(x = 0\\) for the \\(y\\)-axis.","workingLatex":"3t = 0 \\;\\Rightarrow\\; t = 0","explanation":"The \\(y\\)-intercept occurs where \\(x = 0\\)."},{"stepNumber":2,"description":"Find \\(y\\) at \\(t = 0\\).","workingLatex":"y = 0^2 + 1 = 1","explanation":"Substitute into the \\(y\\)-equation."},{"stepNumber":3,"description":"State the intercept.","workingLatex":"(0, 1)","explanation":"The curve meets the \\(y\\)-axis at \\((0, 1)\\)."}],"finalAnswer":"\\((0, 1)\\)."}},
  {"id":"y2pe1-050","topicRef":"y2pe1","topicTitle":"Parametric Equations 57","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = t^2 - 1,\\ y = t^2 - 4\\). Find its \\(x\\)-intercept(s).","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Set \\(y = 0\\).","workingLatex":"t^2 - 4 = 0 \\;\\Rightarrow\\; t = \\pm 2","explanation":"Solve for the parameter at the \\(x\\)-axis."},{"stepNumber":2,"description":"Find \\(x\\) at \\(t = \\pm 2\\).","workingLatex":"x = (\\pm 2)^2 - 1 = 3","explanation":"Because \\(x\\) depends only on \\(t^2\\), both \\(t = 2\\) and \\(t = -2\\) give the same \\(x = 3\\)."},{"stepNumber":3,"description":"Interpret.","workingLatex":"(3, 0)\\ \\text{(reached twice)}","explanation":"There is a single \\(x\\)-intercept \\((3, 0)\\), visited at both parameter values."}],"finalAnswer":"Single point \\((3, 0)\\) (traversed twice)."}},
  {"id":"y2pe1-051","topicRef":"y2pe1","topicTitle":"Parametric Equations 20","difficulty":"Foundation","questionText":"Write \\(y = e^x\\) parametrically.","marks":1,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Set \\(x = t\\).","workingLatex":"x = t","explanation":"Parametrise \\(y = e^x\\) by letting the parameter be \\(x\\)."},{"stepNumber":2,"description":"Express \\(y\\).","workingLatex":"y = e^t","explanation":"Substitute \\(x = t\\) into \\(y = e^x\\)."}],"finalAnswer":"\\(x = t, y = e^t\\)."}},
  {"id":"y2pe1-052","topicRef":"y2pe1","topicTitle":"Parametric Equations 21","difficulty":"Foundation","questionText":"Give two different parametric representations of the line \\(y = 2x\\).","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Take the obvious parametrisation.","workingLatex":"x = t,\\quad y = 2t","explanation":"Setting \\(x = t\\) gives \\(y = 2x = 2t\\): the line \\(y = 2x\\)."},{"stepNumber":2,"description":"Reparametrise with a different function.","workingLatex":"x = t^3,\\quad y = 2t^3","explanation":"Any monotonic substitution works: with \\(x = t^3\\), \\(y = 2x = 2t^3\\) traces the same line. Parametrisations are not unique."}],"finalAnswer":"\\((t, 2t)\\) or \\((t^3, 2t^3)\\) etc."}},
  {"id":"y2pe1-053","topicRef":"y2pe1","topicTitle":"Parametric Equations 58","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = 1 + 3\\cos t,\\ y = -2 + 3\\sin t\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Isolate the trig functions.","workingLatex":"\\cos t = \\tfrac{x - 1}{3},\\quad \\sin t = \\tfrac{y + 2}{3}","explanation":"Subtract the centre coordinates and divide by the radius 3."},{"stepNumber":2,"description":"Apply the Pythagorean identity.","workingLatex":"\\left(\\tfrac{x - 1}{3}\\right)^2 + \\left(\\tfrac{y + 2}{3}\\right)^2 = 1","explanation":"Square and add to remove \\(t\\)."},{"stepNumber":3,"description":"Clear denominators.","workingLatex":"(x - 1)^2 + (y + 2)^2 = 9","explanation":"Multiply by \\(3^2 = 9\\): a circle of radius 3 centred at \\((1, -2)\\)."}],"finalAnswer":"\\((x - 1)^2 + (y + 2)^2 = 9\\)."}},
  {"id":"y2pe1-054","topicRef":"y2pe1","topicTitle":"Parametric Equations 66","difficulty":"Challenge","questionText":"A curve has parametric equations \\(x = t^3 - t,\\ y = t^2\\). Find the point where the curve crosses itself.","marks":4,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Set up the self-intersection condition.","workingLatex":"t_1 \\ne t_2,\\quad x(t_1) = x(t_2),\\quad y(t_1) = y(t_2)","explanation":"A self-crossing means two *different* parameter values give the same point."},{"stepNumber":2,"description":"Equate the \\(y\\)-coordinates.","workingLatex":"t_1^2 = t_2^2 \\;\\Rightarrow\\; t_2 = -t_1","explanation":"Equal \\(y\\) forces \\(t_1^2 = t_2^2\\); the new solution (with \\(t_1 \\ne t_2\\)) is \\(t_2 = -t_1\\)."},{"stepNumber":3,"description":"Equate the \\(x\\)-coordinates.","workingLatex":"t_1^3 - t_1 = (-t_1)^3 - (-t_1) = -t_1^3 + t_1","explanation":"Substitute \\(t_2 = -t_1\\) into \\(x = t^3 - t\\) and set equal to the value at \\(t_1\\)."},{"stepNumber":4,"description":"Solve for \\(t_1\\).","workingLatex":"2t_1^3 - 2t_1 = 0 \\;\\Rightarrow\\; t_1(t_1 - 1)(t_1 + 1) = 0","explanation":"Collect and factor; \\(t_1 = 0\\) is the trivial case, so take \\(t_1 = \\pm 1\\)."},{"stepNumber":5,"description":"Find the crossing point.","workingLatex":"t = \\pm 1:\\ x = 1 - 1 = 0,\\ y = 1","explanation":"Both \\(t = 1\\) and \\(t = -1\\) land on \\((0, 1)\\), so the curve crosses itself there."}],"finalAnswer":"Self-intersection at \\((0, 1)\\) (for \\(t = \\pm 1\\))."}},
  {"id":"y2pe1-055","topicRef":"y2pe1","topicTitle":"Parametric Equations 67","difficulty":"Challenge","questionText":"A curve has parametric equations \\(x = \\cos 2t,\\ y = \\sin t\\). Find its Cartesian equation.","marks":4,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Apply the double-angle identity.","workingLatex":"x = \\cos 2t = 1 - 2\\sin^2 t","explanation":"Use \\(\\cos 2t = 1 - 2\\sin^2 t\\) to write \\(x\\) purely in terms of \\(\\sin t\\)."},{"stepNumber":2,"description":"Substitute \\(y = \\sin t\\).","workingLatex":"x = 1 - 2y^2","explanation":"Since \\(y = \\sin t\\), replace \\(\\sin^2 t\\) by \\(y^2\\). The parameter is eliminated."}],"finalAnswer":"\\(x = 1 - 2y^2\\)."}},
  {"id":"y2pe1-056","topicRef":"y2pe1","topicTitle":"Parametric Equations 22","difficulty":"Foundation","questionText":"Does \\(x = t^2, y = t^3\\) pass through the origin?","marks":1,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Set both coordinates to zero.","workingLatex":"x = t^2 = 0\\ \\text{and}\\ y = t^3 = 0","explanation":"The origin is reached only if some single \\(t\\) makes both \\(x\\) and \\(y\\) vanish."},{"stepNumber":2,"description":"Solve.","workingLatex":"t = 0","explanation":"Both \\(t^2 = 0\\) and \\(t^3 = 0\\) hold at \\(t = 0\\), so the curve passes through the origin there."}],"finalAnswer":"Yes, at \\(t = 0\\)."}},
  {"id":"y2pe1-057","topicRef":"y2pe1","topicTitle":"Parametric Equations 23","difficulty":"Foundation","questionText":"A curve has parametric equations \\(x = 4t^2,\\ y = 2t\\). Find the value of \\(t\\) for which \\((x, y) = (4, 2)\\).","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Use \\(x = 4\\).","workingLatex":"4t^2 = 4 \\;\\Rightarrow\\; t^2 = 1 \\;\\Rightarrow\\; t = \\pm 1","explanation":"Solve the \\(x\\)-equation; there are two candidate parameters."},{"stepNumber":2,"description":"Pick the one matching \\(y = 2\\).","workingLatex":"y = 2t = 2 \\;\\Rightarrow\\; t = 1","explanation":"Only \\(t = 1\\) gives \\(y = 2\\); \\(t = -1\\) would give \\(y = -2\\)."}],"finalAnswer":"\\(t = 1\\) (taking positive root of \\(x = 4\\))."}},
  {"id":"y2pe1-058","topicRef":"y2pe1","topicTitle":"Parametric Equations 24","difficulty":"Foundation","questionText":"Determine whether the point \\((9, 6)\\) lies on the curve \\(x = t^2,\\ y = 2t\\).","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Find \\(t\\) from \\(x = 9\\).","workingLatex":"t^2 = 9 \\;\\Rightarrow\\; t = \\pm 3","explanation":"The \\(x\\)-equation gives two candidate parameter values."},{"stepNumber":2,"description":"Match \\(y = 6\\).","workingLatex":"y = 2t = 6 \\;\\Rightarrow\\; t = 3","explanation":"Only \\(t = 3\\) gives \\(y = 6\\), so the point lies on the curve."}],"finalAnswer":"Yes, at \\(t = 3\\)."}},
  {"id":"y2pe1-059","topicRef":"y2pe1","topicTitle":"Parametric Equations 59","difficulty":"Standard","questionText":"State restrictions and the Cartesian equation of \\(x = \\tfrac{1}{t}, y = 1 + t\\).","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Make \\(t\\) the subject of \\(x\\).","workingLatex":"x = \\tfrac{1}{t} \\;\\Rightarrow\\; t = \\tfrac{1}{x}","explanation":"Invert the reciprocal. This already shows \\(x \\ne 0\\) (and \\(t \\ne 0\\))."},{"stepNumber":2,"description":"Substitute into \\(y = 1 + t\\).","workingLatex":"y = 1 + \\tfrac{1}{x}","explanation":"Replace \\(t\\) by \\(\\tfrac{1}{x}\\)."},{"stepNumber":3,"description":"State equation with restriction.","workingLatex":"y = 1 + \\tfrac{1}{x},\\quad x \\ne 0","explanation":"Since \\(t \\ne 0\\) forces \\(x \\ne 0\\), the point \\((0, \\cdot)\\) is excluded."}],"finalAnswer":"\\(y = 1 + \\tfrac{1}{x}\\), \\(x \\ne 0\\)."}},
  {"id":"y2pe1-060","topicRef":"y2pe1","topicTitle":"Parametric Equations 60","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = t + 1,\\ y = 2t\\). Find the point where it meets the line \\(y = x\\).","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric","intersection"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Impose the line \\(y = x\\).","workingLatex":"2t = t + 1","explanation":"On \\(y = x\\) the two coordinate expressions are equal; set \\(y = x\\)."},{"stepNumber":2,"description":"Solve for \\(t\\).","workingLatex":"t = 1","explanation":"Subtract \\(t\\) from both sides."},{"stepNumber":3,"description":"Find the point.","workingLatex":"x = 1 + 1 = 2,\\ y = 2(1) = 2","explanation":"Substitute back: the curve meets \\(y = x\\) at \\((2, 2)\\)."}],"finalAnswer":"\\((2, 2)\\)."}},
  {"id":"y2pe1-061","topicRef":"y2pe1","topicTitle":"Parametric Equations 68","difficulty":"Challenge","questionText":"A curve has parametric equations \\(x = \\cos 2\\theta,\\ y = 2\\sin\\theta\\). Find its Cartesian equation.","marks":4,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Apply the double-angle identity.","workingLatex":"x = \\cos 2\\theta = 1 - 2\\sin^2\\theta","explanation":"Rewrite \\(\\cos 2\\theta\\) using \\(1 - 2\\sin^2\\theta\\) so only \\(\\sin\\theta\\) remains."},{"stepNumber":2,"description":"Express \\(\\sin\\theta\\) via \\(y\\).","workingLatex":"\\sin\\theta = \\tfrac{y}{2}","explanation":"From \\(y = 2\\sin\\theta\\)."},{"stepNumber":3,"description":"Substitute and simplify.","workingLatex":"x = 1 - 2\\left(\\tfrac{y}{2}\\right)^2 = 1 - \\tfrac{y^2}{2}","explanation":"Square the fraction: \\(2 \\cdot \\tfrac{y^2}{4} = \\tfrac{y^2}{2}\\)."}],"finalAnswer":"\\(x = 1 - \\tfrac{y^2}{2}\\)."}},
  {"id":"y2pe1-062","topicRef":"y2pe1","topicTitle":"Parametric Equations 25","difficulty":"Foundation","questionText":"Verify that \\((3, 0)\\) lies on the ellipse \\(x = 3\\cos t, y = 2\\sin t\\).","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Test \\(t = 0\\) on the ellipse.","workingLatex":"x = 3\\cos 0 = 3,\\quad y = 2\\sin 0 = 0","explanation":"Try the angle that makes the trig values simplest. At \\(\\theta = 0\\), \\(\\cos 0 = 1\\) and \\(\\sin 0 = 0\\)."},{"stepNumber":2,"description":"Compare with \\((3, 0)\\).","workingLatex":"(3, 0)\\ \\checkmark","explanation":"Both coordinates match, so \\((3, 0)\\) is on the ellipse, at \\(t = 0\\)."}],"finalAnswer":"Yes, at \\(t = 0\\)."}},
  {"id":"y2pe1-063","topicRef":"y2pe1","topicTitle":"Parametric Equations 26","difficulty":"Foundation","questionText":"For \\(x = t^2, y = 2t\\), give two points on the curve.","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Pick two parameter values.","workingLatex":"x = t^2,\\quad y = 2t","explanation":"Any two values of \\(t\\) give two points; choose convenient ones such as \\(t = 1\\) and \\(t = -1\\)."},{"stepNumber":2,"description":"Evaluate at \\(t = 1\\) and \\(t = -1\\).","workingLatex":"t = 1: (1, 2);\\quad t = -1: (1, -2)","explanation":"Both give \\(x = 1\\) (since \\(x = t^2\\)) but opposite \\(y\\): the curve is symmetric in the \\(x\\)-axis."}],"finalAnswer":"\\((1, 2), (1, -2)\\)."}},
  {"id":"y2pe1-064","topicRef":"y2pe1","topicTitle":"Parametric Equations 61","difficulty":"Standard","questionText":"Eliminate \\(t\\) from \\(x = a + r\\cos t, y = b + r\\sin t\\).","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Isolate the trig functions.","workingLatex":"\\cos t = \\tfrac{x - a}{r},\\quad \\sin t = \\tfrac{y - b}{r}","explanation":"Subtract the centre offsets \\(a, b\\) and divide by \\(r\\) so each side is a single trig function."},{"stepNumber":2,"description":"Apply \\(\\cos^2 t + \\sin^2 t = 1\\).","workingLatex":"\\left(\\tfrac{x - a}{r}\\right)^2 + \\left(\\tfrac{y - b}{r}\\right)^2 = 1","explanation":"Square and add to eliminate \\(t\\)."},{"stepNumber":3,"description":"Clear the denominator.","workingLatex":"(x - a)^2 + (y - b)^2 = r^2","explanation":"Multiply through by \\(r^2\\): a circle of radius \\(r\\) centred at \\((a, b)\\)."}],"finalAnswer":"\\((x - a)^2 + (y - b)^2 = r^2\\)."}},
  {"id":"y2pe1-065","topicRef":"y2pe1","topicTitle":"Parametric Equations 62","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = t^2,\\ y = 2t^3\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Square \\(y\\) to use even powers.","workingLatex":"y^2 = 4t^6 = 4(t^2)^3","explanation":"Squaring removes the \\(\\pm\\) from \\(t = \\pm\\sqrt x\\); write \\(t^6 = (t^2)^3\\)."},{"stepNumber":2,"description":"Substitute \\(x = t^2\\).","workingLatex":"y^2 = 4x^3","explanation":"Replace \\(t^2\\) by \\(x\\). This is the Cartesian equation."}],"finalAnswer":"\\(y^2 = 4x^3\\)."}},
  {"id":"y2pe1-066","topicRef":"y2pe1","topicTitle":"Parametric Equations 27","difficulty":"Foundation","questionText":"A particle moves along \\(x = 3t, y = 4t\\) from \\(t = 0\\) to \\(t = 1\\). Find the distance travelled.","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Recognise straight-line motion.","workingLatex":"x = 3t,\\quad y = 4t \\;\\Rightarrow\\; y = \\tfrac{4}{3}x","explanation":"Both coordinates are linear in \\(t\\), so the path is a straight line; distance is the length of the displacement."},{"stepNumber":2,"description":"Find the displacement over \\(0 \\le t \\le 1\\).","workingLatex":"\\Delta x = 3,\\ \\Delta y = 4","explanation":"From \\(t = 0\\) at \\((0,0)\\) to \\(t = 1\\) at \\((3, 4)\\)."},{"stepNumber":3,"description":"Apply Pythagoras.","workingLatex":"\\sqrt{3^2 + 4^2} = \\sqrt{25}","explanation":"Distance \\(= \\sqrt{(\\Delta x)^2 + (\\Delta y)^2}\\)."},{"stepNumber":4,"description":"Evaluate.","workingLatex":"= 5","explanation":"The particle travels 5 units — a 3-4-5 triangle."}],"finalAnswer":"5 units."}},
  {"id":"y2pe1-067","topicRef":"y2pe1","topicTitle":"Parametric Equations 69","difficulty":"Challenge","questionText":"A curve has parametric equations \\(x = \\cos\\theta,\\ y = \\sin 2\\theta\\). Find its Cartesian equation.","marks":4,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Expand the double angle.","workingLatex":"y = \\sin 2\\theta = 2\\sin\\theta\\cos\\theta = 2x\\sin\\theta","explanation":"Use \\(\\cos\\theta = x\\) to write \\(y\\) in terms of \\(x\\) and \\(\\sin\\theta\\)."},{"stepNumber":2,"description":"Express \\(\\sin\\theta\\) via \\(x\\).","workingLatex":"\\sin\\theta = \\pm\\sqrt{1 - x^2}","explanation":"From \\(\\cos^2\\theta + \\sin^2\\theta = 1\\) with \\(\\cos\\theta = x\\)."},{"stepNumber":3,"description":"Square to remove the \\(\\pm\\).","workingLatex":"y^2 = 4x^2(1 - x^2)","explanation":"Square \\(y = 2x\\sin\\theta\\) and substitute \\(\\sin^2\\theta = 1 - x^2\\); the \\(\\pm\\) disappears."}],"finalAnswer":"\\(y^2 = 4x^2(1 - x^2)\\)."}},
  {"id":"y2pe1-068","topicRef":"y2pe1","topicTitle":"Parametric Equations 70","difficulty":"Challenge","questionText":"A curve has parametric equations \\(x = 2 - t^2,\\ y = t^3 - 3t\\). Find all points where the curve crosses itself.","marks":5,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Set up the self-intersection condition.","workingLatex":"t_1 \\ne t_2,\\quad x(t_1) = x(t_2),\\quad y(t_1) = y(t_2)","explanation":"A self-crossing needs two different parameters giving the same point."},{"stepNumber":2,"description":"Equate the \\(x\\)-coordinates.","workingLatex":"2 - t_1^2 = 2 - t_2^2 \\;\\Rightarrow\\; t_2 = -t_1","explanation":"Equal \\(x\\) forces \\(t_1^2 = t_2^2\\); the non-trivial case is \\(t_2 = -t_1\\)."},{"stepNumber":3,"description":"Equate the \\(y\\)-coordinates.","workingLatex":"t_1^3 - 3t_1 = -t_1^3 + 3t_1","explanation":"Substitute \\(t_2 = -t_1\\) into \\(y = t^3 - 3t\\) (an odd function) and set equal to the value at \\(t_1\\)."},{"stepNumber":4,"description":"Solve for \\(t_1\\).","workingLatex":"2t_1^3 - 6t_1 = 0 \\;\\Rightarrow\\; t_1(t_1^2 - 3) = 0","explanation":"So \\(t_1 = 0\\) (trivial) or \\(t_1 = \\pm\\sqrt 3\\)."},{"stepNumber":5,"description":"Find the crossing point.","workingLatex":"t = \\pm\\sqrt 3:\\ x = 2 - 3 = -1,\\ y = 3\\sqrt3 - 3\\sqrt3 = 0","explanation":"Both \\(t = \\sqrt3\\) and \\(t = -\\sqrt3\\) give \\((-1, 0)\\), the self-intersection."}],"finalAnswer":"Self-intersection at \\((-1, 0)\\) (for \\(t = \\pm\\sqrt 3\\))."}},
  {"id":"y2pe1-069","topicRef":"y2pe1","topicTitle":"Parametric Equations 28","difficulty":"Foundation","questionText":"For the circle \\(x = 5\\cos\\theta, y = 5\\sin\\theta\\), find points at \\(\\theta = 0\\) and \\(\\theta = \\pi\\).","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Evaluate at \\(\\theta = 0\\).","workingLatex":"x = 5\\cos 0 = 5,\\quad y = 5\\sin 0 = 0","explanation":"Use \\(\\cos 0 = 1\\), \\(\\sin 0 = 0\\)."},{"stepNumber":2,"description":"Evaluate at \\(\\theta = \\pi\\).","workingLatex":"x = 5\\cos\\pi = -5,\\quad y = 5\\sin\\pi = 0","explanation":"Use \\(\\cos\\pi = -1\\), \\(\\sin\\pi = 0\\)."},{"stepNumber":3,"description":"State the points.","workingLatex":"(5, 0)\\ \\text{and}\\ (-5, 0)","explanation":"These are the ends of the horizontal diameter of the radius-5 circle."}],"finalAnswer":"\\((5, 0)\\) and \\((-5, 0)\\)."}},
  {"id":"y2pe1-070","topicRef":"y2pe1","topicTitle":"Parametric Equations 29","difficulty":"Foundation","questionText":"For \\(x = t^2, y = t^3\\), for what \\(t\\) values is \\(\\tfrac{dy}{dt} = 0\\)?","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Differentiate \\(y = t^3\\) with respect to \\(t\\).","workingLatex":"\\tfrac{dy}{dt} = 3t^2","explanation":"Apply the power rule to the \\(y\\)-equation; we want where this rate is zero."},{"stepNumber":2,"description":"Set the derivative to zero.","workingLatex":"3t^2 = 0 \\;\\Rightarrow\\; t = 0","explanation":"\\(3t^2 = 0\\) only when \\(t = 0\\). (This is where the curve has a horizontal tangent / cusp.)"}],"finalAnswer":"\\(t = 0\\)."}},
  {"id":"y2pe1-071","topicRef":"y2pe1","topicTitle":"Parametric Equations 71","difficulty":"Challenge","questionText":"A curve has parametric equations \\(x = e^t + e^{-t},\\ y = e^t - e^{-t}\\). Find its Cartesian equation.","marks":4,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Square each equation.","workingLatex":"x^2 = e^{2t} + 2 + e^{-2t},\\quad y^2 = e^{2t} - 2 + e^{-2t}","explanation":"Squaring a sum/difference gives the same outer terms but opposite middle term \\(2\\,e^t e^{-t} = 2\\)."},{"stepNumber":2,"description":"Subtract to cancel \\(e^{2t} + e^{-2t}\\).","workingLatex":"x^2 - y^2 = (e^{2t} + 2 + e^{-2t}) - (e^{2t} - 2 + e^{-2t})","explanation":"Subtracting removes the exponential terms, leaving only the constants."},{"stepNumber":3,"description":"Simplify.","workingLatex":"x^2 - y^2 = 4","explanation":"\\(2 - (-2) = 4\\). A hyperbola; the curve is the right branch since \\(x = e^t + e^{-t} \\ge 2\\)."}],"finalAnswer":"\\(x^2 - y^2 = 4\\) (hyperbola)."}},
];
